template <bool Purposed, class Result>
TicketRequest<Purposed, Result>& TicketRequest<Purposed, Result>::enhanceChildrenIfNeeded() & {
    return *this;
}

class query_factory {
    ContextBinding binding_;

public:
    explicit query_factory(UserContext& user_context) : binding_(user_context) {}

    TenantRequest<false> tenantsMinimal() const {
        return TenantRequest<false>(binding_.get(), true);
    }

    TenantRequest<false> tenants() const {
        return TenantRequest<false>(binding_.get());
    }

    TenantRequest<false> tenantsWithChildren() const {
        return TenantRequest<false>(binding_.get(), true, false)
            .unlimited()
            .selectSelfFields()
            .enhanceChildrenIfNeeded();
    }

    ReceiptRequest<false> receiptsMinimal() const {
        return ReceiptRequest<false>(binding_.get(), true);
    }

    ReceiptRequest<false> receipts() const {
        return ReceiptRequest<false>(binding_.get());
    }

    ReceiptRequest<false> receiptsWithChildren() const {
        return ReceiptRequest<false>(binding_.get(), true, false)
            .unlimited()
            .selectSelfFields()
            .enhanceChildrenIfNeeded();
    }

    ReceiptRequest<false> receiptByReceiptNumber(const ReceiptNumber& value) const {
        return receipts().withReceiptNumberIs(value).limit(2);
    }

    TicketRequest<false> ticketsMinimal() const {
        return TicketRequest<false>(binding_.get(), true);
    }

    TicketRequest<false> tickets() const {
        return TicketRequest<false>(binding_.get());
    }

    TicketRequest<false> ticketsWithChildren() const {
        return TicketRequest<false>(binding_.get(), true, false)
            .unlimited()
            .selectSelfFields()
            .enhanceChildrenIfNeeded();
    }

    TicketRequest<false> ticketByTicketNumber(const TicketNumber& value) const {
        return tickets().withTicketNumberIs(value).limit(2);
    }
};
